//go:build ignore

package main
import("context";"encoding/hex";"encoding/json";"fmt";"math/big";"os";"time";"github.com/ethereum/go-ethereum";"github.com/ethereum/go-ethereum/common";"github.com/ethereum/go-ethereum/crypto";"github.com/ethereum/go-ethereum/ethclient")
func main(){ctx,cancel:=context.WithTimeout(context.Background(),55*time.Second);defer cancel();c,e:=ethclient.DialContext(ctx,"https://ethereum-sepolia-rpc.publicnode.com");must(e);id,e:=c.ChainID(ctx);must(e);if id.Cmp(big.NewInt(11155111))!=0{panic("wrong network")};b,e:=os.ReadFile("docs/evidence/vault-sepolia-2026-09-19/compiled-ETHVault.json");must(e);var a struct{Compiler string;Evm struct{Bytecode struct{Object string};DeployedBytecode struct{Object string}}};must(json.Unmarshal(b,&a));code,e:=hex.DecodeString(a.Evm.Bytecode.Object);must(e);var accounts []struct{Address string;Name string};b,e=os.ReadFile("docs/evidence/vault-sepolia-2026-09-19/accounts-before.json");must(e);must(json.Unmarshal(b,&accounts));out:=map[string]any{"chainId":id.String(),"compiler":a.Compiler,"rpc":"https://ethereum-sepolia-rpc.publicnode.com","scope":"Known project wallet CREATE addresses only; not an exhaustive search of all external deployers"};rows:=[]any{};for _,ac:=range accounts{addr:=common.HexToAddress(ac.Address);n,e:=c.NonceAt(ctx,addr,nil);must(e);bal,e:=c.BalanceAt(ctx,addr,nil);must(e);gas,e:=c.EstimateGas(ctx,ethereum.CallMsg{From:addr,Data:code});must(e);price,e:=c.SuggestGasPrice(ctx);must(e);row:=map[string]any{"address":addr.Hex(),"name":ac.Name,"nonce":n,"balanceWei":bal.String(),"deploymentGasEstimate":gas,"gasPriceWei":price.String(),"estimatedDeploymentFeeWei":new(big.Int).Mul(new(big.Int).SetUint64(gas),price).String()};matches:=[]any{};if n>50{row["scanSkipped"]="nonce exceeds 50"}else{for i:=uint64(0);i<n;i++{ca:=crypto.CreateAddress(addr,i);runtime,e:=c.CodeAt(ctx,ca,nil);must(e);if len(runtime)>0{matches=append(matches,map[string]any{"nonce":i,"address":ca.Hex(),"runtimeMatchesETHVault":hex.EncodeToString(runtime)==a.Evm.DeployedBytecode.Object,"runtimeBytes":len(runtime)})}}};row["createdContracts"]=matches;rows=append(rows,row)};out["wallets"]=rows;b,e=json.MarshalIndent(out,"","  ");must(e);must(os.WriteFile("docs/evidence/vault-sepolia-2026-09-19/chain-preflight.json",append(b,'\n'),0644));fmt.Println(string(b))}
func must(e error){if e!=nil{panic(e)}}
